  "bullets": [
    {
      "bullet": "The Canadian financial system remains resilient to severe solvency and liquidity shocks, supported by bank nonperforming loans below 0.6 percent and a Domestic Stability Buffer of 3.5 percent.",
      "section_ids": ["S01", "S06"]
    },
    {
      "bullet": "Nonbank financial institutions grew by about 12 percent year-over-year in 2024, presenting rising cross-border linkages and liquidity risks that require expanded system-wide stress testing.",
