{
  "growth_drivers_strengths": [
    {
      "item": "Resilient financial system with strong capital and liquidity buffers",
      "explanation": "Banks and major nonbank financial institutions maintain robust capital and liquidity buffers, showing resilience to severe solvency and liquidity shocks in FSAP stress tests.",
      "evidence_quote": "The financial system is resilient to severe solvency and liquidity shocks, consistent with FSAP findings",
      "section_id": "S01"
    },
    {
      "item": "USMCA exemptions cushioning external trade shock impacts",
      "explanation": "Deep continental trade integration and USMCA exemptions continue to shelter most bilateral trade, helping cushion Canada's economy against significant U.S. tariff increases.",
      "evidence_quote": "USMCA exemptions continue to shelter most bilateral trade",
      "section_id": "S05"
    },
    {
      "item": "Strong macroeconomic buffers including positive net international investment position",
      "explanation": "Canada maintains strong policy frameworks and fundamentals, including a positive net international investment position and reliable access to external financing, providing essential economic buffers.",
      "evidence_quote": "Canada’s strong policy frameworks and fundamentals—including a positive net international investment position and stable external financing—provide important buffers.",
      "section_id": "S01"
    },
    {
      "item": "Internationally competitive tax incentives reducing marginal effective rates",
      "explanation": "Policies like the Productivity Super-Deduction and Accelerated Investment Incentive reduce the marginal effective tax rate on new capital by over two percentage points, enhancing tax competitiveness.",
      "evidence_quote": "the Productivity Super-Deduction and Accelerated Investment Incentive reduce the marginal effective tax rate on new capital by over two percentage points",
      "section_id": "S12"
    },
    {
      "item": "Well-anchored inflation expectations enabling measured monetary policy easing",
      "explanation": "Soft demand and firm cost absorption have contained tariff pass-through to prices, keeping CPI inflation hovering near target and allowing accommodative interest rate cuts.",
      "evidence_quote": "Inflation is projected to remain close to the 2 percent target, supported by softer demand and firms’ absorption of higher costs.",
      "section_id": "S01"
    },
    {
      "item": "High growth potential from eliminating internal interprovincial trade barriers",
      "explanation": "Removing non-geographic internal trade barriers across provinces could increase real GDP by up to 7 percent over time through improved labor productivity and resource allocation.",
      "evidence_quote": "Fully eliminating non-geographic internal trade barriers could raise real GDP by up to 7 percent over time, largely through efficiency gains",
      "section_id": "S12"
    }
  ],
  "systemic_vulnerabilities_challenges": [
    {
      "item": "Elevated household leverage and high debt-service burdens",
      "explanation": "Persistent high household debt and debt-service burdens leave private consumption vulnerable to employment shocks and ongoing mortgage repricing amid historically strained housing affordability.",
      "evidence_quote": "Elevated household debt and ongoing mortgage repricing leave some households exposed to income and employment shocks",
      "section_id": "S13"
    },
    {
      "item": "CRE exposures and expanding nonbank financial intermediation risks",
      "explanation": "Pension funds and insurers face material commercial real estate exposures, while growing nonbank intermediation and leverage in repo markets risk amplifying financial market volatility.",
      "evidence_quote": "pockets of vulnerability persist, including commercial real estate exposures — particularly among pension funds and insurers—and the expanding role of nonbank financial intermediation.",
      "section_id": "S01"
    },
    {
      "item": "Weak productivity growth and persistent gaps in business dynamism",
